import { createHash } from 'node:crypto';

export const EXPECTED_COMPARISON = Object.freeze({
  admissionSha256: '517718573822d0010056361844960c124f2fd6f2cf51537cf504e4da61d237c0',
  helperSha256: '7da53e0014fc6f499b8341c03246388244b608e76f2da10742f56808d34b0fbc',
  routeReviewSha256: '00a054d0dee57117a0b689ccfb6c62550286870ad6819d1f0308686061796e6a',
  guardReviewSha256: 'c61f9fded47337615d33941cacb05d20a0d096ae93e2a73fc1e996ca5d2765b8',
  helperReviewSha256: 'cad16a6ae5f87a0c2fbafd9f5670bb3ad6e79eea2e71fc9e0bcffc2299e06d16',
  historicalInventorySha256: 'e1d0cd97046e21b308894d5f8757f8fc1fa580550e3ec700aa7ab0e1519bbb92',
  beforeRouteSha256: 'ab5018c64668dfe197755849aee1a2b3c5947f6c3da21e8d18869e998f3f9e01',
  afterRouteSha256: 'fd9b1115130d523629e58b5fcef06fe5355eedc8afd12d6dacc998623c89ff37',
  guardSha256: '8ffb4f7470e9b139201001b80b7a14f629f7d56a5f67187044e54dfb7492eb17',
  baselineFixtureSha256: '8ebe51aec86d8e5990a6f8391bb8e823c7cd661d2d7369e3b35909ef74722de3',
  tableDigest: 'cec9b5e4ef42e38acea843f0ebba92b39cf2b42c1f6c137f6ed62d575fec5d64',
  companyId: '8b90c706-1710-494d-b12d-02eef88eacb7',
  reportId: 'de6bc76f-9fbf-461a-8e2d-b5f8d6097a86',
  versionId: '146977ae-a4ac-4985-8158-aa6c581d71d2',
  database: 'm78_ops_continuation_20260922',
});

const direct = ['direct_register', 'direct_version', 'direct_report'] as const;
const routes = ['register', 'version', 'version_export', 'version_proof', 'report', 'report_download', 'report_snapshot', 'report_proof'] as const;
const expectedOperations = [...direct, ...routes.map((name) => `before_${name}`), ...routes.map((name) => `after_${name}`)];
const check: (value: unknown, message: string) => asserts value = (value, message) => { if (!value) throw new Error(message); };
const same = (left: unknown, right: unknown) => JSON.stringify(left) === JSON.stringify(right);
const hex = (value: unknown) => typeof value === 'string' && /^[a-f0-9]{64}$/.test(value);
const finite = (value: unknown) => typeof value === 'number' && Number.isFinite(value) && value >= 0;

export const sha256 = (value: string | Uint8Array) => createHash('sha256').update(value).digest('hex');

export function validateM78GetLocalComparison(result: any) {
  const x = EXPECTED_COMPARISON;
  check(result?.status === 'm78_get_route_local_comparison_passed', 'comparison status');
  check(result.admissionSha256 === x.admissionSha256, 'admission binding');
  check(result.historicalSourceInventorySha256 === x.historicalInventorySha256, 'historical inventory binding');
  check(result.sourcesVerifiedBeforeAndAfter === true && result.historicalSources === 173, 'source closure');
  check(result.beforeRouteSha256 === x.beforeRouteSha256 && result.afterRouteSha256 === x.afterRouteSha256, 'route bindings');
  check(result.database === x.database && result.companyId === x.companyId, 'local target binding');
  check(result.reportId === x.reportId && result.versionId === x.versionId, 'retained identity binding');
  check(result.hostCalls === 0 && result.applicationWrites === 0 && result.httpPostRequests === 0, 'zero external/write counters');
  check(result.warmupsPerCase === 1 && result.measuredSamplesPerCase === 3, 'sample contract');
  check(result.noHostedTimingOrSlaClaim === true, 'timing limitation');
  check(result.localConnectionsClosed === true, 'connection closure');
  check(result.digestScope === '121 neuvetra base-table row sets; no sequence/settings/external-effect claim', 'digest scope');
  for (const side of ['tableDigestsBefore', 'tableDigestsAfter'] as const) {
    check(result[side]?.tableCount === 121 && result[side]?.sha256 === x.tableDigest, side);
  }
  check(same(result.tableDigestsBefore, result.tableDigestsAfter), 'digest equality');
  check(Array.isArray(result.cases) && result.cases.length === 19, 'case count');
  check(same(result.cases.map((item: any) => item.operation), expectedOperations), 'case order');
  const byName = new Map<string, any>();
  for (const item of result.cases) {
    check(!byName.has(item.operation), 'unique operation');
    byName.set(item.operation, item);
    check(Array.isArray(item.samples) && item.samples.length === 4, 'four samples ' + item.operation);
    check(item.samples[0]?.phase === 'warmup' && item.samples[0]?.sample === 0, 'warmup ordinal ' + item.operation);
    for (let index = 1; index < 4; index++) check(item.samples[index]?.phase === 'measured' && item.samples[index]?.sample === index, 'measured ordinal ' + item.operation);
    const first = item.samples[0];
    check(hex(first.bodySha256) && Number.isInteger(first.bytes) && first.bytes > 0, 'body evidence ' + item.operation);
    check(Array.isArray(first.headers) && first.headers.every((pair: unknown) => Array.isArray(pair) && pair.length === 2 && pair.every((value) => typeof value === 'string')), 'headers ' + item.operation);
    for (const sample of item.samples) {
      check(sample.bodySha256 === first.bodySha256 && sample.bytes === first.bytes && sample.status === first.status && same(sample.headers, first.headers), 'stable response ' + item.operation);
      for (const field of ['transactions', 'sqlQueries', 'stateReads', 'corporateReads'] as const) check(Number.isInteger(sample[field]) && sample[field] >= 0, field + ' ' + item.operation);
      check(finite(sample.sqlMs) && finite(sample.totalMs) && sample.sqlMs <= sample.totalMs, 'timing values ' + item.operation);
    }
    const measured = item.samples.slice(1).map((sample: any) => sample.totalMs).sort((a: number, b: number) => a - b);
    check(item.medianMs === measured[1] && item.maxMs === measured[2], 'timing summary ' + item.operation);
    const route = item.operation.startsWith('before_') || item.operation.startsWith('after_');
    check(item.samples.every((sample: any) => sample.status === (route ? 200 : null) && same(sample.headers, route ? first.headers : [])), 'status/header kind ' + item.operation);
  }
  for (const name of routes) {
    const before = byName.get(`before_${name}`), after = byName.get(`after_${name}`);
    check(before && after, 'paired route ' + name);
    check(before.samples.every((sample: any) => sample.bodySha256 === after.samples[0].bodySha256 && sample.bytes === after.samples[0].bytes && sample.status === after.samples[0].status && same(sample.headers, after.samples[0].headers)), 'before/after response ' + name);
    const root = name === 'register';
    check(before.samples.every((sample: any) => sample.stateReads === (root ? 1 : 2) && sample.sqlQueries === (root ? 44 : 86) && sample.corporateReads === (root ? 10 : 20) && sample.transactions === (root ? 2 : 3)), 'before structure ' + name);
    check(after.samples.every((sample: any) => sample.stateReads === 1 && sample.sqlQueries === 44 && sample.corporateReads === 10 && sample.transactions === 2), 'after structure ' + name);
  }
  for (const name of direct) check(byName.get(name).samples.every((sample: any) => sample.stateReads === 1 && sample.sqlQueries === 42 && sample.corporateReads === 10 && sample.transactions === 1), 'direct structure ' + name);
  return {
    status: 'm78_get_route_local_comparison_independently_validated',
    cases: 19,
    routePairs: 8,
    measuredSamples: 57,
    beforeSpecificStateReads: 2,
    afterSpecificStateReads: 1,
    beforeSpecificSqlQueries: 86,
    afterSpecificSqlQueries: 44,
    tableDigest: x.tableDigest,
  };
}

import { expect, test } from 'bun:test';
import { createHash } from 'node:crypto';
import { EXPECTED_COMPARISON, validateM78GetLocalComparison } from './m78-get-local-comparison-independent-review';

const hash = (value: string) => createHash('sha256').update(value).digest('hex');
const routes = ['register', 'version', 'version_export', 'version_proof', 'report', 'report_download', 'report_snapshot', 'report_proof'] as const;

function fixture(): any {
  const make = (operation: string) => {
    const route = operation.startsWith('before_') || operation.startsWith('after_');
    const root = operation.endsWith('register');
    const beforeSpecific = operation.startsWith('before_') && !root;
    const bodyName = operation.replace(/^(before|after)_/, '');
    const samples = Array.from({ length: 4 }, (_, sample) => ({
      phase: sample === 0 ? 'warmup' : 'measured', sample,
      transactions: route ? (beforeSpecific ? 3 : 2) : 1,
      sqlQueries: beforeSpecific ? 86 : (route ? 44 : 42),
      stateReads: beforeSpecific ? 2 : 1,
      corporateReads: beforeSpecific ? 20 : 10,
      sqlMs: 10 + sample,
      totalMs: 20 + sample,
      bytes: 100 + bodyName.length,
      bodySha256: hash(bodyName),
      status: route ? 200 : null,
      headers: route ? [['cache-control', 'no-store'], ['content-type', 'application/json']] : [],
    }));
    return { operation, samples, medianMs: 22, maxMs: 23 };
  };
  return {
    status: 'm78_get_route_local_comparison_passed',
    admissionSha256: EXPECTED_COMPARISON.admissionSha256,
    historicalSourceInventorySha256: EXPECTED_COMPARISON.historicalInventorySha256,
    sourcesVerifiedBeforeAndAfter: true,
    historicalSources: 173,
    extraPins: [],
    beforeRouteSha256: EXPECTED_COMPARISON.beforeRouteSha256,
    afterRouteSha256: EXPECTED_COMPARISON.afterRouteSha256,
    database: EXPECTED_COMPARISON.database,
    companyId: EXPECTED_COMPARISON.companyId,
    reportId: EXPECTED_COMPARISON.reportId,
    versionId: EXPECTED_COMPARISON.versionId,
    hostCalls: 0,
    applicationWrites: 0,
    httpPostRequests: 0,
    tableDigestsBefore: { tableCount: 121, sha256: EXPECTED_COMPARISON.tableDigest },
    tableDigestsAfter: { tableCount: 121, sha256: EXPECTED_COMPARISON.tableDigest },
    digestScope: '121 neuvetra base-table row sets; no sequence/settings/external-effect claim',
    warmupsPerCase: 1,
    measuredSamplesPerCase: 3,
    cases: [make('direct_register'), make('direct_version'), make('direct_report'), ...routes.map((name) => make(`before_${name}`)), ...routes.map((name) => make(`after_${name}`))],
    noHostedTimingOrSlaClaim: true,
    localConnectionsClosed: true,
  };
}

const clone = <T>(value: T): T => structuredClone(value);

test('positive exact 19-case comparison is accepted', () => {
  expect(validateM78GetLocalComparison(fixture())).toEqual({
    status: 'm78_get_route_local_comparison_independently_validated', cases: 19, routePairs: 8, measuredSamples: 57,
    beforeSpecificStateReads: 2, afterSpecificStateReads: 1, beforeSpecificSqlQueries: 86, afterSpecificSqlQueries: 44,
    tableDigest: EXPECTED_COMPARISON.tableDigest,
  });
});

test('altered case count, body hash and header pair are refused', () => {
  const count = fixture(); count.cases.pop(); expect(() => validateM78GetLocalComparison(count)).toThrow('case count');
  const body = fixture(); body.cases[12]!.samples[2]!.bodySha256 = hash('changed'); expect(() => validateM78GetLocalComparison(body)).toThrow('stable response');
  const header = fixture(); for (const sample of header.cases.find((item: any) => item.operation === 'after_report')!.samples) sample.headers[0]![1] = 'public'; expect(() => validateM78GetLocalComparison(header)).toThrow('before/after response');
});

test('altered sample shape, digest and cleanup are refused', () => {
  const samples = fixture(); samples.cases[0]!.samples.pop(); expect(() => validateM78GetLocalComparison(samples)).toThrow('four samples');
  const ordinal = fixture(); ordinal.cases[0]!.samples[1]!.sample = 2; expect(() => validateM78GetLocalComparison(ordinal)).toThrow('measured ordinal');
  const digest = fixture(); digest.tableDigestsAfter.sha256 = hash('changed'); expect(() => validateM78GetLocalComparison(digest)).toThrow('tableDigestsAfter');
  const cleanup = fixture(); cleanup.localConnectionsClosed = false; expect(() => validateM78GetLocalComparison(cleanup)).toThrow('connection closure');
});

test('altered query structure, source closure and zero-write counters are refused', () => {
  const queries = fixture(); queries.cases.find((item: any) => item.operation === 'after_report')!.samples[3]!.sqlQueries = 45; expect(() => validateM78GetLocalComparison(queries)).toThrow('after structure');
  const sources = fixture(); sources.sourcesVerifiedBeforeAndAfter = false; expect(() => validateM78GetLocalComparison(sources)).toThrow('source closure');
  const writes = fixture(); writes.applicationWrites = 1; expect(() => validateM78GetLocalComparison(writes)).toThrow('zero external/write counters');
  const admission = fixture(); admission.admissionSha256 = hash('changed'); expect(() => validateM78GetLocalComparison(admission)).toThrow('admission binding');
});

import { expect, test } from 'bun:test';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { EXPECTED_COMPARISON, sha256, validateM78GetLocalComparison } from './m78-get-local-comparison-independent-review';

const ROOT = resolve(import.meta.dir, '../..');
const resultPath = resolve(ROOT, 'evaluations/research-qa/m78-get-local-comparison-result.json');
const sourcePath = resolve(ROOT, 'evaluations/research-qa/m78-get-local-comparison-source.json');
const inventoryPath = resolve(ROOT, 'evaluations/research-qa/m78-continuation4-preparation-source-pins.json');
const RESULT_SHA256 = 'caae59a5d5704c53b6d61f901d30dee55be01b7f890c62e7d6e5c1b1b7931417';
const SOURCE_ARCHIVE_SHA256 = 'a3bec8644f040ec875ee4f7eb8d3fbf4c181bd7d4281b517644c35f189842f9e';
const clone = <T>(value: T): T => structuredClone(value);
const actualBytes = readFileSync(resultPath);
const actual: any = JSON.parse(actualBytes.toString('utf8'));
const sourceBytes = readFileSync(sourcePath);
const source: any = JSON.parse(sourceBytes.toString('utf8'));

test('actual frozen result and portable operator source archive are exactly bound', () => {
  expect(sha256(actualBytes)).toBe(RESULT_SHA256);
  expect(sha256(sourceBytes)).toBe(SOURCE_ARCHIVE_SHA256);
  expect(source.status).toBe('m78_get_local_comparison_frozen_operator_source');
  expect(source.files).toHaveLength(5);
  for (const file of source.files) expect(sha256(file.text)).toBe(file.sha256);
  const byPath = new Map<string, any>(source.files.map((file: any) => [file.path, file]));
  const helper = byPath.get('.superpowers/m78-get-route-comparative.ts');
  const admissionFile = byPath.get('.superpowers/m78-get-route-comparative-admission.json');
  expect(helper.sha256).toBe(EXPECTED_COMPARISON.helperSha256);
  expect(admissionFile.sha256).toBe(EXPECTED_COMPARISON.admissionSha256);
  expect((helper.text.match(/await verify\(\)/g) ?? [])).toHaveLength(2);
  expect(helper.text).toContain("p.path===ROUTE?admission.afterRouteSha256:p.sha256");
  expect(helper.text).toContain("check(same(beforeDigest,afterDigest),'Base-table data changed')");
  expect(helper.text).toContain("await Promise.allSettled([Promise.resolve().then(()=>runtime?.close()),Promise.resolve().then(()=>admin?.close())])");

  const admission = JSON.parse(admissionFile.text);
  expect(admission.status).toBe('m78_get_route_comparative_source_admitted');
  expect(admission.beforeRouteSha256).toBe(EXPECTED_COMPARISON.beforeRouteSha256);
  expect(admission.afterRouteSha256).toBe(EXPECTED_COMPARISON.afterRouteSha256);
  expect(admission.routeReview.sha256).toBe(EXPECTED_COMPARISON.routeReviewSha256);
  expect(admission.guardReview.sha256).toBe(EXPECTED_COMPARISON.guardReviewSha256);
  expect(actual.extraPins).toEqual(admission.extraPins);
  for (const pin of admission.extraPins as { path: string; sha256: string }[]) {
    if (pin.path === '.superpowers/m78-get-route-comparative.ts') expect(pin.sha256).toBe(helper.sha256);
    else expect(sha256(readFileSync(resolve(ROOT, pin.path)))).toBe(pin.sha256);
  }
  const routeReceipt = JSON.parse(readFileSync(resolve(ROOT, admission.routeReview.path), 'utf8'));
  expect([routeReceipt.status, routeReceipt.reviewerId, routeReceipt.materialFindingsOpen, routeReceipt.candidateRouteSha256]).toEqual([
    'm78_get_route_independent_source_review_passed', '/root/m78_transport_probe', 0, EXPECTED_COMPARISON.afterRouteSha256,
  ]);
  const guardReceipt = JSON.parse(readFileSync(resolve(ROOT, admission.guardReview.path), 'utf8'));
  expect([guardReceipt.status, guardReceipt.reviewerId, guardReceipt.materialFindingsOpen, guardReceipt.candidateGuardSha256]).toEqual([
    'm78_get_probe_guard_independent_review_passed', '/root/m78_transport_probe', 0, EXPECTED_COMPARISON.guardSha256,
  ]);
  const helperReceipt = JSON.parse(readFileSync(resolve(ROOT, 'evaluations/research-qa/m78-get-root-comparative-review-result.json'), 'utf8'));
  expect([helperReceipt.status, helperReceipt.reviewerId, helperReceipt.materialFindingsOpen, helperReceipt.candidateHelperSha256]).toEqual([
    'm78_get_root_comparative_source_review_passed', '/root/m78_transport_probe', 0, EXPECTED_COMPARISON.helperSha256,
  ]);
  expect(validateM78GetLocalComparison(actual).measuredSamples).toBe(57);
});

test('current closure is the 172 retained historical pins plus the accepted route', () => {
  const inventoryBytes = readFileSync(inventoryPath);
  expect(sha256(inventoryBytes)).toBe(EXPECTED_COMPARISON.historicalInventorySha256);
  const pins: { path: string; sha256: string }[] = JSON.parse(inventoryBytes.toString('utf8'));
  expect(pins).toHaveLength(173);
  for (const pin of pins) {
    const expected = pin.path === 'apps/site-api/src/workspace/m78-routes.ts' ? EXPECTED_COMPARISON.afterRouteSha256 : pin.sha256;
    expect(sha256(readFileSync(resolve(ROOT, pin.path)))).toBe(expected);
  }
});

test('actual evidence refuses altered count, hash, header and sample ordinal', () => {
  const count = clone(actual); count.cases.pop(); expect(() => validateM78GetLocalComparison(count)).toThrow('case count');
  const body = clone(actual); body.cases[4].samples[2].bodySha256 = '0'.repeat(64); expect(() => validateM78GetLocalComparison(body)).toThrow('stable response');
  const header = clone(actual); for (const sample of header.cases.find((item: any) => item.operation === 'after_report').samples) sample.headers[0][1] += '-changed'; expect(() => validateM78GetLocalComparison(header)).toThrow('before/after response');
  const ordinal = clone(actual); ordinal.cases[0].samples[3].sample = 2; expect(() => validateM78GetLocalComparison(ordinal)).toThrow('measured ordinal');
});

test('actual evidence refuses altered digest, cleanup, closure and write counters', () => {
  const digest = clone(actual); digest.tableDigestsAfter.sha256 = '1'.repeat(64); expect(() => validateM78GetLocalComparison(digest)).toThrow('tableDigestsAfter');
  const cleanup = clone(actual); cleanup.localConnectionsClosed = false; expect(() => validateM78GetLocalComparison(cleanup)).toThrow('connection closure');
  const closure = clone(actual); closure.historicalSources = 172; expect(() => validateM78GetLocalComparison(closure)).toThrow('source closure');
  const write = clone(actual); write.applicationWrites = 1; expect(() => validateM78GetLocalComparison(write)).toThrow('zero external/write counters');
});

test('actual evidence refuses changed direct and optimized structural counts', () => {
  const direct = clone(actual); direct.cases.find((item: any) => item.operation === 'direct_version').samples[0].sqlQueries = 44; expect(() => validateM78GetLocalComparison(direct)).toThrow('direct structure');
  const optimized = clone(actual); optimized.cases.find((item: any) => item.operation === 'after_report_proof').samples[1].stateReads = 2; expect(() => validateM78GetLocalComparison(optimized)).toThrow('after structure');
  const baseline = clone(actual); baseline.cases.find((item: any) => item.operation === 'before_report').samples[1].sqlQueries = 85; expect(() => validateM78GetLocalComparison(baseline)).toThrow('before structure');
});

