import {createHash} from 'node:crypto'
import {readFile,writeFile} from 'node:fs/promises'
import {resolve} from 'node:path'
import {pathToFileURL} from 'node:url'
import {createPostgresConnection,HostedWorkspaceDatabase,type WorkspaceConnection} from '../packages/neuvetra-database/src/index'
import {m78FixtureAuthorities} from '../tools/staging/m78-backend-fixture'
import {M78_REVIEWED_POLICY} from '../packages/neuvetra-database/src/m78-policy'
import {m78CanonicalJson as canonical} from '../packages/neuvetra-database/src/m78-validation'
import type {M78RouteDatabase} from '../apps/site-api/src/workspace/m78-routes'

const ROOT='C:/Users/nimab/.codex/worktrees/4441/Neuvetra',CANDIDATE='C:/Users/nimab/.codex/worktrees/m78-get-performance/Neuvetra'
const ROUTE='apps/site-api/src/workspace/m78-routes.ts',GUARD='evaluations/research-qa/m78-continuation4-get-perf-probe.ts'
const COMPANY='8b90c706-1710-494d-b12d-02eef88eacb7',DATABASE='m78_ops_continuation_20260922',PROJECT='icockcoguyadhryzydvl',ORIGIN='http://127.0.0.1:47821'
const ADMISSION=resolve(ROOT,'.superpowers/m78-get-route-comparative-admission.json'),OUT=resolve(ROOT,'.superpowers/m78-get-route-comparative-result.json'),LOCK=OUT+'.lock'
const hash=(v:string|Uint8Array)=>createHash('sha256').update(v).digest('hex')
const check:(v:unknown,m:string)=>asserts v=(v,m)=>{if(!v)throw Error(m)}
const same=(a:unknown,b:unknown)=>canonical(a)===canonical(b)
type Pin={path:string;sha256:string}
type Sample={phase:'warmup'|'measured';sample:number;transactions:number;sqlQueries:number;stateReads:number;corporateReads:number;sqlMs:number;totalMs:number;bytes:number;bodySha256:string;status:number|null;headers:[string,string][]}

async function digests(db:WorkspaceConnection){return db.transaction(async tx=>{
 await tx.exec('set transaction isolation level repeatable read read only')
 const names=(await tx.query<{name:string}>("select table_name name from information_schema.tables where table_schema='neuvetra' and table_type='BASE TABLE' order by table_name")).rows.map(r=>r.name)
 check(names.length===121,'Expected 121 base tables')
 const rows=[] as {table:string;count:number;sha256:string}[]
 for(const name of names){check(/^[a-z0-9_]+$/.test(name),'Unsafe table name');const values=(await tx.query<{row:string}>(`select neuvetra.m67_canonical(to_jsonb(t)) row from neuvetra.${name} t order by neuvetra.m67_canonical(to_jsonb(t)) collate "C"`)).rows.map(r=>r.row);rows.push({table:name,count:values.length,sha256:hash(values.join('\n'))})}
 return {tableCount:rows.length,sha256:hash(canonical(rows))}
})}

async function main(){
 check(resolve('.')===resolve(ROOT),'Original checkout working directory required')
 const admissionBytes=await readFile(ADMISSION),admission=JSON.parse(admissionBytes.toString('utf8'))
 check(admission.status==='m78_get_route_comparative_source_admitted','Source admission required')
 check(admission.beforeRouteSha256==='ab5018c64668dfe197755849aee1a2b3c5947f6c3da21e8d18869e998f3f9e01','Historical route required')
 const historicalBytes=await readFile(resolve(ROOT,'evaluations/research-qa/m78-continuation4-preparation-source-pins.json'))
 check(hash(historicalBytes)==='e1d0cd97046e21b308894d5f8757f8fc1fa580550e3ec700aa7ab0e1519bbb92','Historical inventory changed')
 const historical:Pin[]=JSON.parse(historicalBytes.toString('utf8'));check(historical.length===173,'Expected full historical source closure')
 const verify=async()=>{
  for(const p of historical){check(hash(await readFile(resolve(ROOT,p.path)))===p.sha256,'Original source changed: '+p.path);check(hash(await readFile(resolve(CANDIDATE,p.path)))===(p.path===ROUTE?admission.afterRouteSha256:p.sha256),'Candidate source changed: '+p.path)}
  for(const p of admission.extraPins as Pin[])check(hash(await readFile(resolve(ROOT,p.path)))===p.sha256,'Extra source changed: '+p.path)
  check((admission.extraPins as Pin[]).some(p=>p.path===GUARD),'Guard pin missing')
  check((admission.extraPins as Pin[]).some(p=>p.path==='.superpowers/m78-get-route-comparative.ts'),'Helper pin missing')
 }
